+export async function listTools() {
+  return [
+    {
+      name: TOOL_NAME,
+      description: 'Look up a customer by their unique customer ID and return their details.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          customer_id: { type: 'string', description: 'The unique customer identifier.' }
+        },
+        required: ['customer_id'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args) {
+  if (name !== TOOL_NAME) {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Invalid arguments: expected an object');
+  }
+
+  const allowed = ['customer_id'];
+  for (const key of Object.keys(args)) {
+    if (!allowed.includes(key)) {
+      throw new Error(`Invalid arguments: unexpected field "${key}"`);
+    }
+  }
+
+  if (!('customer_id' in args)) {
+    throw new Error('Invalid arguments: "customer_id" is required');
+  }
+
+  const { customer_id } = args;
+  if (typeof customer_id !== 'string') {
+    throw new Error('Invalid arguments: "customer_id" must be a string');
+  }
+
+  const customer = customers[customer_id];
+  if (!customer) {
+    throw new Error(`Unknown customer: ${customer_id}`);
+  }
+
+  return {
+    content: [
+      {
+        type: 'text',
+        text: `${customer.name} (${customer.tier})`
+      }
+    ]
+  };
